class FakeUserApi:
    """Stands in for a real HTTP server so the contract can be tested offline."""
    def __init__(self):
        self.users = {1: {'id': 1, 'name': 'Ana', 'email': 'ana@example.com'}}
        self.next_id = 2

    def get_user(self, user_id):
        if user_id in self.users:
            return 200, self.users[user_id]
        return 404, {'error': 'not found'}

    def create_user(self, name, email):
        new_id = self.next_id
        self.users[new_id] = {'id': new_id, 'name': name, 'email': email}
        self.next_id += 1
        return 201, self.users[new_id]

api = FakeUserApi()

status, body = api.get_user(1)
assert status == 200 and body['name'] == 'Ana'
print(f'get existing user: {status}')

status, body = api.get_user(9999)
assert status == 404
print(f'get missing user: {status}')

status, body = api.create_user('Jane', 'jane@example.com')
assert status == 201 and body['id'] == 2
print(f'create user: {status} id={body["id"]}')
